<?php
require_once __DIR__ . '/payment-common.php';
function ep_base(): string{return strtolower(app_env('EASYPAISA_ENV','sandbox'))==='live'?'https://easypay.easypaisa.com.pk':'https://easypaystg.easypaisa.com.pk';}
function ep_hash(string $value,string $key): string{$key=substr(str_pad($key,16,"\0"),0,16);$pad=16-(strlen($value)%16);$value.=str_repeat(chr($pad),$pad);return base64_encode(openssl_encrypt($value,'AES-128-ECB',$key,OPENSSL_RAW_DATA|OPENSSL_ZERO_PADDING));}
function ep_hosted(array $o): array{$now=new DateTimeImmutable('now',new DateTimeZone('Asia/Karachi'));$store=app_env('EASYPAISA_STORE_ID');$f=['amount'=>number_format((float)$o['total'],1,'.',''),'storeId'=>$store,'postBackURL'=>rtrim(app_env('APP_URL'),'/').'/api/easypaisa.php?action=return','orderRefNum'=>order_prefix($o['order_no'],'EP'),'expiryDate'=>$now->modify('+1 hour')->format('Ymd His'),'autoRedirect'=>'1','paymentMethod'=>'MA_PAYMENT_METHOD','emailAddr'=>$o['email'],'mobileNum'=>$o['phone']];$raw='amount='.$f['amount'].'&autoRedirect=1&emailAddr='.$f['emailAddr'].'&mobileNum='.$f['mobileNum'].'&orderRefNum='.$f['orderRefNum'].'&paymentMethod=MA_PAYMENT_METHOD&postBackURL='.$f['postBackURL'].'&storeId='.$f['storeId'];$f['merchantHashedReq']=ep_hash($raw,app_env('EASYPAISA_HASH_KEY'));return$f;}
function ep_callback(array $d): array{$hash=(string)($d['merchantHashedReq']??$d['hash']??'');if($hash==='')return['ok'=>false,'paid'=>false,'error'=>'EasyPaisa callback hash is missing'];$raw=(string)($d['response']??'');if($raw===''){$tmp=$d;unset($tmp['merchantHashedReq'],$tmp['hash']);$raw=json_encode($tmp,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}if(!hash_equals(ep_hash($raw,app_env('EASYPAISA_HASH_KEY')),$hash))return['ok'=>false,'paid'=>false,'error'=>'EasyPaisa callback hash verification failed'];$ref=(string)($d['orderRefNum']??$d['orderId']??$d['order_id']??'');$no=str_starts_with($ref,'EP-')?'ZB-'.substr($ref,3):$ref;$paid=(string)($d['responseCode']??$d['response_code']??'')==='0000';if($paid&&$no!=='')mark_order_paid($no,(string)($d['transactionId']??$ref));return['ok'=>true,'paid'=>$paid,'order_no'=>$no,'message'=>$paid?'Payment received':(string)($d['responseDesc']??'Payment pending')];}
if(($_GET['action']??'')==='return'){if(($_SERVER['REQUEST_METHOD']??'')!=='POST')api_json(405,['ok'=>false,'error'=>'Invalid callback']);$r=ep_callback($_POST);if(!$r['ok'])api_json(400,$r);header('Location: '.rtrim(app_env('APP_URL'),'/').'/checkout.html?payment='.($r['paid']?'paid':'pending').'&order_no='.rawurlencode($r['order_no']));exit;}
api_method('POST');$in=api_input();try{$no=(string)($in['order_no']??'');$o=payment_order($no);if($o['payment_method']!=='easypaisa')api_json(422,['ok'=>false,'error'=>'Payment method mismatch']);$store=app_env('EASYPAISA_STORE_ID');$username=app_env('EASYPAISA_USERNAME');$password=app_env('EASYPAISA_PASSWORD');$key=app_env('EASYPAISA_HASH_KEY');if(!$store||!$username||!$password||!$key)api_json(503,['ok'=>false,'error'=>'EasyPaisa credentials are not configured']);$base=ep_base();$action=(string)($in['action']??'');if($action==='hosted')api_json(200,['ok'=>true,'url'=>$base.'/easypay/Index.jsf','fields'=>ep_hosted($o)]);if($action!=='ma')api_json(422,['ok'=>false,'error'=>'Unknown EasyPaisa action']);$mobile=preg_replace('/\D/','',(string)($in['mobile']??''));if(!preg_match('/^03\d{9}$/',$mobile))api_json(422,['ok'=>false,'error'=>'Enter a valid EasyPaisa mobile number']);$gatewayOrder=order_prefix($no,'EP');$storeId=ctype_digit($store)?(int)$store:$store;$body=['orderId'=>$gatewayOrder,'storeId'=>$storeId,'transactionAmount'=>number_format((float)$o['total'],1,'.',''),'transactionType'=>'MA','mobileAccountNo'=>$mobile,'emailAddress'=>$o['email']?:'customer@example.com'];$headers=['Content-Type: application/json','Accept: application/json','Credentials: '.base64_encode($username.':'.$password)];$init=gateway_post($base.'/easypay-service/rest/v4/initiate-ma-transaction',$headers,json_encode($body));if((string)($init['data']['responseCode']??'')!=='0000')api_json(200,['ok'=>true,'paid'=>false,'message'=>(string)($init['data']['responseDesc']??'EasyPaisa request was not accepted')]);$inq=gateway_post($base.'/easypay-service/rest/v4/inquire-transaction',$headers,json_encode(['orderId'=>$gatewayOrder,'storeId'=>$storeId]));$paid=(string)($inq['data']['responseCode']??'')==='0000';if($paid)mark_order_paid($no,(string)($inq['data']['transactionId']??$gatewayOrder));api_json(200,['ok'=>true,'paid'=>$paid,'order_no'=>$no,'message'=>$paid?'Payment received':(string)($inq['data']['responseDesc']??'Payment pending')]);}catch(Throwable $e){api_json(502,['ok'=>false,'error'=>$e->getMessage()]);}
